#!/usr/bin/env bash
set -u

VERSION="10.2.94"
NAME="AetherForge-Rust-Reforge-v10.2.94-AetherStream-Dual-Schema-Adapter"
DOWNLOADS="$HOME/Downloads"
PAYLOAD="$DOWNLOADS/${NAME}-source.zip"
SRC="$DOWNLOADS/$NAME"
VERIFY="$DOWNLOADS/AetherForge-Rust-Reforge-v${VERSION}-AETHERSTREAM-DUAL-SCHEMA-ADAPTER-VERIFY.txt"
CACHE="$HOME/.cache/aetherforge/aetherstream-dual-schema-adapter-v${VERSION}"
AETHERSTREAM_ZIP="$SRC/AetherStream-v10.2.50-source.zip"
AETHERSTREAM_ROOT="$CACHE/AetherStream-v10.2.50"
APP="$AETHERSTREAM_ROOT/apps/aetherstream"
BIN_SOURCE="$APP/src/bin/aetherforge-control-center-aetherstream-adapter.rs"
MANIFEST="$APP/Cargo.toml"
BUILT="$AETHERSTREAM_ROOT/target/release/aetherforge-control-center-aetherstream-adapter"
INSTALLED="$HOME/.local/lib/aetherforge/aetherstream-control-center-typed-adapter"
BACKUP="${XDG_STATE_HOME:-$HOME/.local/state}/aetherforge/rust-reforge/${VERSION}/backups/aetherstream-control-center-typed-adapter"

BRIDGE="$HOME/.local/lib/aetherforge/aetherforge-control-bridge-readonly"
CONSUMER="$HOME/.local/lib/aetherforge/aetherforge-control-center-bridge-consumer"
CONTROL_CENTER="/usr/bin/aether-control-center"
DISPLAY="$HOME/.local/lib/aetherforge/aetherforge-display-autoscan-shadow"
PROTOCOL="$HOME/.local/lib/aetherforge/aetherforge-control-bridge-protocol"
AETHERSTREAM_AUDIOD="$HOME/.local/bin/aetherstream-audiod"
PLASMA="${XDG_CONFIG_HOME:-$HOME/.config}/plasma-org.kde.plasma.desktop-appletsrc"

EXPECTED_PAYLOAD_SHA="72b863993720e01774e20941580628d83a69541d6d4b3a80fcba01d489362f97"
EXPECTED_AETHERSTREAM_SHA="e777e48361829bb29c4765e7adc9a97d752b28ff060b10d78db18216c9274bde"
EXPECTED_ADAPTER_SHA="0541a5064723f156dc067631b79e0ccfa107aaf61ae98137c0dac18c6ecef07b"
EXPECTED_BRIDGE_SHA="45cafe82d14c830c27dd88a8651d323ff3b080bdd0c91584e93e43a8d3ad15b3"
EXPECTED_CONSUMER_SHA="ec22255a1eb8e8cc8e76ffa5184ddfd06c6ddff1d6e18979d487b95ca2b36b48"
EXPECTED_CONTROL_CENTER_SHA="2ce1d3370f46030566f24e50403e022e77fca89c3c79db7a711aed63102c3c88"
EXPECTED_DISPLAY_SHA="bde738f09a56f900486f2f90c2f1ecb39ca507f081efecbb124eddcf2fe1b35e"
EXPECTED_PROTOCOL_SHA="d8f380568526ae0a87f263d5ab49ae40a0abd39129370da1960e372c1a2ce092"
EXPECTED_AETHERSTREAM_AUDIOD_SHA="22f5ade3271612da8f19aff73b78d4e005077563032c89cb6bcb33c71d0ecfeb"
INSTALLED_NEW=0

mkdir -p "$DOWNLOADS"
: > "$VERIFY"

log() { printf '%s\n' "$*" | tee -a "$VERIFY"; }
hash_path() {
  local p="$1"
  if [[ -f "$p" || -L "$p" ]]; then sha256sum "$p" | awk '{print $1}'; else printf 'MISSING'; fi
}
fail() {
  rc="${1:-1}"; shift || true
  log "${*:-AETHERSTREAM_DUAL_SCHEMA_ADAPTER_FAILED}"
  if [[ "$INSTALLED_NEW" = 1 && -f "$BACKUP" ]]; then
    install -m755 "$BACKUP" "$INSTALLED" >>"$VERIFY" 2>&1 || true
    log "ADAPTER_ROLLBACK_SHA256=$(hash_path "$INSTALLED")"
  fi
  log "AETHERSTREAM_DUAL_SCHEMA_ADAPTER_RELEASE=FAIL"
  log "VERIFY_FILE=$VERIFY"
  exit "$rc"
}

log "=== AetherForge v${VERSION} AetherStream Dual-Schema Typed Adapter ==="
log "MODE=RUST_ONLY_READ_ONLY_ADAPTER_COMPATIBILITY_REPAIR"
log "ROOT_CAUSE=POSTCARD_POSITIONAL_STATE_SCHEMA_MISMATCH_10_2_47_VS_10_2_50"
log "IPC_PROTOCOL_VERSION=1"
log "SUPPORTED_STATE_SCHEMA_1=10.2.47"
log "SUPPORTED_STATE_SCHEMA_2=10.2.50"
log "CONTROL_MODE=READ_ONLY_GET_STATE"
log "PREINSTALL_LIVE_ONLINE_GATE=REQUIRED"
log "AETHERSTREAM_AUDIOD_REPLACEMENT=NO"
log "FORGEHX_ROUTING_MUTATION=NO"
log "BRIDGE_REPLACEMENT=NO"
log "CONSUMER_REPLACEMENT=NO"
log "CONTROL_CENTER_REPLACEMENT=NO"
log "DISPLAY_SERVICE_REPLACEMENT=NO"
log "PROTOCOL_BINARY_REPLACEMENT=NO"
log "SYSTEMCTL_EXECUTION=NO"
log "PIPEWIRE_EXECUTION=NO"
log "KSCREEN_EXECUTION=NO"
log "SUDO_REQUIRED=NO"
log "PLASMASHELL_RESTART=NO"
log "AUTOMATIC_REBOOT=NO"

for tool in base64 sha256sum unzip cargo awk grep install sed rustfmt; do
  command -v "$tool" >/dev/null 2>&1 || fail 2 "HOST_TOOL_MISSING=$tool"
done

for required in "$INSTALLED" "$BRIDGE" "$CONSUMER" "$CONTROL_CENTER" "$DISPLAY" "$PROTOCOL" "$AETHERSTREAM_AUDIOD"; do
  [[ -e "$required" ]] || fail 3 "REQUIRED_RUNTIME=MISSING:$required"
done

ADAPTER_BEFORE="$(hash_path "$INSTALLED")"
BRIDGE_BEFORE="$(hash_path "$BRIDGE")"
CONSUMER_BEFORE="$(hash_path "$CONSUMER")"
CONTROL_CENTER_BEFORE="$(hash_path "$CONTROL_CENTER")"
DISPLAY_BEFORE="$(hash_path "$DISPLAY")"
PROTOCOL_BEFORE="$(hash_path "$PROTOCOL")"
AETHERSTREAM_AUDIOD_BEFORE="$(hash_path "$AETHERSTREAM_AUDIOD")"
PLASMA_BEFORE="$(hash_path "$PLASMA")"

log "ADAPTER_SHA256_BEFORE=$ADAPTER_BEFORE"
log "BRIDGE_SHA256_BEFORE=$BRIDGE_BEFORE"
log "CONSUMER_SHA256_BEFORE=$CONSUMER_BEFORE"
log "CONTROL_CENTER_SHA256_BEFORE=$CONTROL_CENTER_BEFORE"
log "DISPLAY_SERVICE_SHA256_BEFORE=$DISPLAY_BEFORE"
log "PROTOCOL_BINARY_SHA256_BEFORE=$PROTOCOL_BEFORE"
log "AETHERSTREAM_AUDIOD_SHA256_BEFORE=$AETHERSTREAM_AUDIOD_BEFORE"
log "PLASMA_CONFIG_SHA256_BEFORE=$PLASMA_BEFORE"

[[ "$ADAPTER_BEFORE" = "$EXPECTED_ADAPTER_SHA" ]] || fail 4 "CURRENT_ADAPTER_SHA_GATE=FAIL:$ADAPTER_BEFORE"
[[ "$BRIDGE_BEFORE" = "$EXPECTED_BRIDGE_SHA" ]] || fail 5 "CURRENT_BRIDGE_SHA_GATE=FAIL:$BRIDGE_BEFORE"
[[ "$CONSUMER_BEFORE" = "$EXPECTED_CONSUMER_SHA" ]] || fail 6 "CURRENT_CONSUMER_SHA_GATE=FAIL:$CONSUMER_BEFORE"
[[ "$CONTROL_CENTER_BEFORE" = "$EXPECTED_CONTROL_CENTER_SHA" ]] || fail 7 "CURRENT_CONTROL_CENTER_SHA_GATE=FAIL:$CONTROL_CENTER_BEFORE"
[[ "$DISPLAY_BEFORE" = "$EXPECTED_DISPLAY_SHA" ]] || fail 8 "CURRENT_DISPLAY_SHA_GATE=FAIL:$DISPLAY_BEFORE"
[[ "$PROTOCOL_BEFORE" = "$EXPECTED_PROTOCOL_SHA" ]] || fail 9 "CURRENT_PROTOCOL_SHA_GATE=FAIL:$PROTOCOL_BEFORE"
[[ "$AETHERSTREAM_AUDIOD_BEFORE" = "$EXPECTED_AETHERSTREAM_AUDIOD_SHA" ]] || fail 10 "CURRENT_AETHERSTREAM_AUDIOD_SHA_GATE=FAIL:$AETHERSTREAM_AUDIOD_BEFORE"
log "CURRENT_RUNTIME_SHA_GATES=PASS"

cat > "$PAYLOAD.b64" <<'AETHERFORGE_V10294_PAYLOAD'
