AAQABAApAgAAG0EFAAAA
AETHERFORGE_V10294_PAYLOAD
base64 -d "$PAYLOAD.b64" > "$PAYLOAD" || fail 11 "PAYLOAD_DECODE=FAIL"
rm -f "$PAYLOAD.b64"
PAYLOAD_SHA="$(sha256sum "$PAYLOAD" | awk '{print $1}')"
[[ "$PAYLOAD_SHA" = "$EXPECTED_PAYLOAD_SHA" ]] || fail 12 "PAYLOAD_SHA256=FAIL:$PAYLOAD_SHA"
log "PAYLOAD_SHA256=PASS:$PAYLOAD_SHA"

ARCHIVE_ROOT="$(unzip -Z1 "$PAYLOAD" | awk -F/ 'NF {print $1; exit}')"
[[ "$ARCHIVE_ROOT" = "$NAME" ]] || fail 13 "ARCHIVE_ROOT_GATE=FAIL:$ARCHIVE_ROOT"
log "ARCHIVE_ROOT_GATE=PASS"

rm -rf "$SRC" "$CACHE"
unzip -q "$PAYLOAD" -d "$DOWNLOADS" || fail 14 "SOURCE_EXTRACT=FAIL"
[[ -f "$SRC/src/main.rs" && -f "$AETHERSTREAM_ZIP" ]] || fail 15 "SOURCE_LAYOUT=FAIL"
log "SOURCE_LAYOUT=PASS"

AETHERSTREAM_SHA="$(sha256sum "$AETHERSTREAM_ZIP" | awk '{print $1}')"
[[ "$AETHERSTREAM_SHA" = "$EXPECTED_AETHERSTREAM_SHA" ]] || fail 16 "AETHERSTREAM_SOURCE_SHA_GATE=FAIL:$AETHERSTREAM_SHA"
log "AETHERSTREAM_SOURCE_SHA_GATE=PASS:$AETHERSTREAM_SHA"

mkdir -p "$CACHE"
unzip -q "$AETHERSTREAM_ZIP" -d "$CACHE" || fail 17 "AETHERSTREAM_EXTRACT=FAIL"
[[ -f "$MANIFEST" ]] || fail 18 "AETHERSTREAM_MANIFEST=MISSING"

cp -f "$SRC/src/main.rs" "$BIN_SOURCE" || fail 19 "ADAPTER_SOURCE_INJECT=FAIL"
if ! grep -Eq '^serde\.workspace = true$' "$MANIFEST"; then
  printf '\nserde.workspace = true\n' >> "$MANIFEST"
fi
if ! grep -Eq '^serde_json\.workspace = true$' "$MANIFEST"; then
  printf 'serde_json.workspace = true\n' >> "$MANIFEST"
fi
log "CACHE_WORKSPACE_SERIALIZATION_DEPS=PASS"

if (cd "$AETHERSTREAM_ROOT" && cargo fmt --check --all) >>"$VERIFY" 2>&1; then
  log "HOST_CARGO_FMT=PASS"
else
  rc=$?; fail "$rc" "HOST_CARGO_FMT=FAIL:$rc"
fi

if (cd "$AETHERSTREAM_ROOT" && cargo clippy -p aetherstream --bin aetherforge-control-center-aetherstream-adapter -- -D warnings) >>"$VERIFY" 2>&1; then
  log "HOST_CARGO_CLIPPY=PASS"
else
  rc=$?; fail "$rc" "HOST_CARGO_CLIPPY=FAIL:$rc"
fi

if (cd "$AETHERSTREAM_ROOT" && cargo test -p aetherstream --bin aetherforge-control-center-aetherstream-adapter --release) >>"$VERIFY" 2>&1; then
  log "HOST_CARGO_TEST=PASS"
else
  rc=$?; fail "$rc" "HOST_CARGO_TEST=FAIL:$rc"
fi

if (cd "$AETHERSTREAM_ROOT" && cargo build -p aetherstream --bin aetherforge-control-center-aetherstream-adapter --release) >>"$VERIFY" 2>&1; then
  log "HOST_CARGO_BUILD=PASS"
else
  rc=$?; fail "$rc" "HOST_CARGO_BUILD=FAIL:$rc"
fi

"$BUILT" --self-test >>"$VERIFY" 2>&1 || fail 20 "BUILT_SELF_TEST=FAIL"
log "BUILT_SELF_TEST=PASS"

log "=== PREINSTALL_LIVE_SNAPSHOT_BEGIN ==="
set +e
PREINSTALL_OUTPUT="$("$BUILT" --snapshot 2>&1)"
PREINSTALL_RC=$?
set -e
printf '%s\n' "$PREINSTALL_OUTPUT" >>"$VERIFY"
log "=== PREINSTALL_LIVE_SNAPSHOT_END ==="
[[ "$PREINSTALL_RC" = 0 ]] || fail 21 "PREINSTALL_LIVE_SNAPSHOT=FAIL:$PREINSTALL_RC"
printf '%s\n' "$PREINSTALL_OUTPUT" | grep -Fq 'AETHERSTREAM_TYPED_ADAPTER_STATUS=ONLINE' || fail 22 "PREINSTALL_LIVE_ONLINE_GATE=FAIL"
printf '%s\n' "$PREINSTALL_OUTPUT" | grep -Eq 'AETHERSTREAM_TYPED_DECODED_SCHEMA=10\.2\.(47|50)' || fail 23 "PREINSTALL_SCHEMA_GATE=FAIL"
log "PREINSTALL_LIVE_ONLINE_GATE=PASS"

mkdir -p "$(dirname "$BACKUP")" "$(dirname "$INSTALLED")"
install -m755 "$INSTALLED" "$BACKUP" || fail 24 "ADAPTER_BACKUP=FAIL"
[[ "$(hash_path "$BACKUP")" = "$EXPECTED_ADAPTER_SHA" ]] || fail 25 "ADAPTER_BACKUP_SHA=FAIL"
log "ADAPTER_BACKUP=PASS:$BACKUP"

install -m755 "$BUILT" "$INSTALLED" || fail 26 "ADAPTER_INSTALL=FAIL"
INSTALLED_NEW=1
NEW_ADAPTER_SHA="$(hash_path "$INSTALLED")"
[[ "$NEW_ADAPTER_SHA" != "$EXPECTED_ADAPTER_SHA" ]] || fail 27 "ADAPTER_INSTALL_SHA_UNCHANGED"
log "ADAPTER_INSTALL=PASS:$NEW_ADAPTER_SHA"

"$INSTALLED" --self-test >>"$VERIFY" 2>&1 || fail 28 "INSTALLED_SELF_TEST=FAIL"
log "INSTALLED_SELF_TEST=PASS"

log "=== INSTALLED_LIVE_SNAPSHOT_BEGIN ==="
"$INSTALLED" --snapshot >>"$VERIFY" 2>&1 || fail 29 "INSTALLED_LIVE_SNAPSHOT=FAIL"
log "=== INSTALLED_LIVE_SNAPSHOT_END ==="
log "INSTALLED_LIVE_SNAPSHOT=PASS"

BRIDGE_AFTER="$(hash_path "$BRIDGE")"
CONSUMER_AFTER="$(hash_path "$CONSUMER")"
CONTROL_CENTER_AFTER="$(hash_path "$CONTROL_CENTER")"
DISPLAY_AFTER="$(hash_path "$DISPLAY")"
PROTOCOL_AFTER="$(hash_path "$PROTOCOL")"
AETHERSTREAM_AUDIOD_AFTER="$(hash_path "$AETHERSTREAM_AUDIOD")"
PLASMA_AFTER="$(hash_path "$PLASMA")"

[[ "$BRIDGE_BEFORE" = "$BRIDGE_AFTER" ]] || fail 30 "BRIDGE_MUTATED"
[[ "$CONSUMER_BEFORE" = "$CONSUMER_AFTER" ]] || fail 31 "CONSUMER_MUTATED"
[[ "$CONTROL_CENTER_BEFORE" = "$CONTROL_CENTER_AFTER" ]] || fail 32 "CONTROL_CENTER_MUTATED"
[[ "$DISPLAY_BEFORE" = "$DISPLAY_AFTER" ]] || fail 33 "DISPLAY_MUTATED"
[[ "$PROTOCOL_BEFORE" = "$PROTOCOL_AFTER" ]] || fail 34 "PROTOCOL_MUTATED"
[[ "$AETHERSTREAM_AUDIOD_BEFORE" = "$AETHERSTREAM_AUDIOD_AFTER" ]] || fail 35 "AETHERSTREAM_AUDIOD_MUTATED"
[[ "$PLASMA_BEFORE" = "$PLASMA_AFTER" ]] || fail 36 "PLASMA_CONFIG_MUTATED"

log "BRIDGE_UNCHANGED=PASS"
log "CONSUMER_UNCHANGED=PASS"
log "CONTROL_CENTER_UNCHANGED=PASS"
log "DISPLAY_SERVICE_UNCHANGED=PASS"
log "PROTOCOL_BINARY_UNCHANGED=PASS"
log "AETHERSTREAM_AUDIOD_UNCHANGED=PASS"
log "FORGEHX_ROUTING_PRESERVED=PASS"
log "PLASMA_CONFIG_UNCHANGED=PASS"
log "CONTROL_MODE=READ_ONLY_GET_STATE"
log "SYSTEMCTL_EXECUTION=NO"
log "PIPEWIRE_EXECUTION=NO"
log "KSCREEN_EXECUTION=NO"
log "AUDIO_ROUTING_CHANGE=NO"
log "PLASMASHELL_RESTART=NO"
log "AUTOMATIC_REBOOT=NO"
log "AETHERSTREAM_DUAL_SCHEMA_ADAPTER_RELEASE=PASS"
log "VERIFY_FILE=$VERIFY"
INSTALLED_NEW=0
